stages.sampleAnswer:
POST /events
  body: { event_id, ad_id, campaign_id, timestamp, user_id, geo, device_type, additional_metadata }
  → 202 Accepted { event_id } (or 200 OK if committed)

GET /metrics
  query: { campaign_id, ad_id, geo?, device_type?, start_time, end_time, bucket_size_sec? }
  → 200 { metrics: [ { time_bucket, click_count, unique_users, spend } ] }

POST /reconcile
  body: { campaign_id, start_time, end_time }
  → 202 { job_id, status }
